#!/usr/bin/perl
use strict;
use warnings;

# Function to check if a number is a prime number
sub is_prime {
    my ($num) = @_;
    return 0 if $num < 2;  # If the number is less than 2, it's not a prime number
    for (my $i = 2; $i * $i <= $num; $i++) {
        return 0 if $num % $i == 0;  # If the number is divisible by any integer from 2 to sqrt($num), it's not a prime number
    }
    return 1;  # If no divisors were found, the number is a prime number
}

# Main program
my $number = 17;  # Example number to check
if (is_prime($number)) {
    print "The number $number is a prime number.\n";
} else {
    print "The number $number is not a prime number.\n";
}
